+      function addRipple(uvX, uvY, amplitude) {
+        ripples[rippleIndex] = {
+          x: uvX,
+          y: uvY,
+          startTime: getNowSeconds(),
+          amplitude: amplitude
+        };
+        rippleIndex = (rippleIndex + 1) % MAX_RIPPLES;
+      }
+
+      let titleBoundsUV = [0, 0, 0, 0];
+      let btnBoundsUV = [0, 0, 0, 0];
+
+      function drawRoundedRect(ctx, x, y, w, h, r) {
+        const radius = Math.min(r, w / 2, h / 2);
+        ctx.beginPath();
+        ctx.moveTo(x + radius, y);
+        ctx.arcTo(x + w, y, x + w, y + h, radius);
+        ctx.arcTo(x + w, y + h, x, y + h, radius);
+        ctx.arcTo(x, y + h, x, y, radius);
+        ctx.arcTo(x, y, x + w, y, radius);
+        ctx.closePath();
+      }
+
+      function updateBgTexture() {
+        const rect = hero.getBoundingClientRect();
+        const dpr = Math.min(window.devicePixelRatio || 1, 2);
+        const width = Math.max(1, Math.round(rect.width * dpr));
+        const height = Math.max(1, Math.round(rect.height * dpr));
+
+        bgCanvas.width = width;
+        bgCanvas.height = height;
+
+        if (bgImageLoaded && bgImage.naturalWidth > 0) {
+          const imgRatio = bgImage.naturalWidth / bgImage.naturalHeight;
+          const canvasRatio = width / height;
+          let drawW = width;
+          let drawH = height;
+          let offsetX = 0;
+          let offsetY = 0;
+
+          if (canvasRatio > imgRatio) {
+            drawH = width / imgRatio;
+            offsetY = (height - drawH) * 0.5;
+          } else {
+            drawW = height * imgRatio;
+            offsetX = (width - drawW) * 0.5;
+          }
+          bgCtx.drawImage(bgImage, offsetX, offsetY, drawW, drawH);
+        } else {
+          const grad = bgCtx.createLinearGradient(0, 0, width, height);
+          grad.addColorStop(0, '#4e342e');
+          grad.addColorStop(0.5, '#3e2723');
+          grad.addColorStop(1, '#271815');
+          bgCtx.fillStyle = grad;
+          bgCtx.fillRect(0, 0, width, height);
+        }
+
+        gl.bindTexture(gl.TEXTURE_2D, bgTexture);
+        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, bgCanvas);
+      }
+
+      function syncHtmlToTexture() {
+        const heroRect = hero.getBoundingClientRect();
+        const dpr = Math.min(window.devicePixelRatio || 1, 2);
+        const width = Math.max(1, Math.round(heroRect.width * dpr));
+        const height = Math.max(1, Math.round(heroRect.height * dpr));
+
+        if (canvas.width !== width || canvas.height !== height) {
+          canvas.width = width;
+          canvas.height = height;
+          gl.viewport(0, 0, width, height);
+          updateBgTexture();
+        }
+
+        domCanvas.width = width;
+        domCanvas.height = height;
+        domCtx.save();
+        domCtx.clearRect(0, 0, width, height);
+        domCtx.scale(dpr, dpr);
+
+        // 1. Rasterize 'Wake Up Your Senses' (<h1>) at its exact DOM position
+        const titleRect = titleEl.getBoundingClientRect();
+        const titleStyle = window.getComputedStyle(titleEl);
+        const titleX = titleRect.left - heroRect.left + titleRect.width * 0.5;
+        const titleY = titleRect.top - heroRect.top + titleRect.height * 0.5;
+
+        titleBoundsUV = [
+          (titleRect.left - heroRect.left) / Math.max(heroRect.width, 1),
+          (titleRect.top - heroRect.top) / Math.max(heroRect.height, 1),
+          titleRect.width / Math.max(heroRect.width, 1),
+          titleRect.height / Math.max(heroRect.height, 1)
+        ];
+
+        domCtx.font = `${titleStyle.fontWeight} ${titleStyle.fontSize} ${titleStyle.fontFamily}`;
+        domCtx.fillStyle = '#ffffff';
+        domCtx.textAlign = 'center';
+        domCtx.textBaseline = 'middle';
+        domCtx.fillText(titleEl.textContent.trim(), titleX, titleY);
+
+        // 2. Rasterize 'Order Now' (.btn) at its exact DOM position
+        const btnRect = ctaEl.getBoundingClientRect();
+        const btnStyle = window.getComputedStyle(ctaEl);
+        const btnX = btnRect.left - heroRect.left;
+        const btnY = btnRect.top - heroRect.top;
+        const btnRadius = parseFloat(btnStyle.borderRadius) || 5;
+
+        btnBoundsUV = [
+          btnX / Math.max(heroRect.width, 1),
+          btnY / Math.max(heroRect.height, 1),
+          btnRect.width / Math.max(heroRect.width, 1),
+          btnRect.height / Math.max(heroRect.height, 1)
+        ];
+
+        drawRoundedRect(domCtx, btnX, btnY, btnRect.width, btnRect.height, btnRadius);
+        domCtx.fillStyle = isBtnHovered ? '#3e2723' : '#4e342e';
+        domCtx.fill();
+
+        domCtx.font = `${btnStyle.fontWeight} ${btnStyle.fontSize} ${btnStyle.fontFamily}`;
+        domCtx.fillStyle = '#ffffff';
+        domCtx.textAlign = 'center';
+        domCtx.textBaseline = 'middle';
+        domCtx.fillText(
+          ctaEl.textContent.trim(),
+          btnX + btnRect.width * 0.5,
+          btnY + btnRect.height * 0.5
+        );
+
+        domCtx.restore();
+
+        gl.bindTexture(gl.TEXTURE_2D, domTexture);
+        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, domCanvas);
+      }
+
+      // Mark hero as WebGL-active so real HTML text/button become transparent overlays
+      // while remaining selectable and clickable in place
+      hero.classList.add('webgl-ready');
+      updateBgTexture();
+      syncHtmlToTexture();
+
+      // Pointer & hover interactions
+      let lastTrailTime = 0;
+      hero.addEventListener('pointermove', function (e) {
+        const rect = hero.getBoundingClientRect();
+        const ux = (e.clientX - rect.left) / Math.max(rect.width, 1);
+        const uy = (e.clientY - rect.top) / Math.max(rect.height, 1);
+        targetMouseUV.x = Math.max(0, Math.min(1, ux));
+        targetMouseUV.y = Math.max(0, Math.min(1, uy));
+        targetHoverIntensity = 1.0;
+
+        const now = getNowSeconds();
+        if (now - lastTrailTime > 0.14) {
+          addRipple(targetMouseUV.x, targetMouseUV.y, 0.45);
+          lastTrailTime = now;
+        }
+      });
+
+      hero.addEventListener('pointerenter', function () {
+        targetHoverIntensity = 1.0;
+      });
+
+      hero.addEventListener('pointerleave', function () {
+        targetHoverIntensity = 0.25;
+      });
+
+      hero.addEventListener('pointerdown', function (e) {
+        const rect = hero.getBoundingClientRect();
+        const ux = (e.clientX - rect.left) / Math.max(rect.width, 1);
+        const uy = (e.clientY - rect.top) / Math.max(rect.height, 1);
+        addRipple(ux, uy, 1.0);
+      });
+
+      titleEl.addEventListener('pointerenter', function () {
+        const cx = titleBoundsUV[0] + titleBoundsUV[2] * 0.5;
+        const cy = titleBoundsUV[1] + titleBoundsUV[3] * 0.5;
+        addRipple(cx, cy, 0.75);
+      });
+
+      ctaEl.addEventListener('pointerenter', function () {
+        isBtnHovered = true;
+        targetBtnHover = 1.0;
+        syncHtmlToTexture();
+        const cx = btnBoundsUV[0] + btnBoundsUV[2] * 0.5;
+        const cy = btnBoundsUV[1] + btnBoundsUV[3] * 0.5;
+        addRipple(cx, cy, 0.85);
+      });
+
+      ctaEl.addEventListener('pointerleave', function () {
+        isBtnHovered = false;
+        targetBtnHover = 0.0;
+        syncHtmlToTexture();
+      });
+
+      window.addEventListener('resize', function () {
+        syncHtmlToTexture();
+      });
+
+      // Trigger initial welcome ripple across 'Wake Up Your Senses'
+      addRipple(0.5, 0.38, 0.85);
+
+      function render() {
+        const now = getNowSeconds();
+
+        mouseUV.x += (targetMouseUV.x - mouseUV.x) * 0.12;
+        mouseUV.y += (targetMouseUV.y - mouseUV.y) * 0.12;
+        currentHoverIntensity += (targetHoverIntensity - currentHoverIntensity) * 0.08;
+        currentBtnHover += (targetBtnHover - currentBtnHover) * 0.12;
+
+        gl.useProgram(program);
+
+        gl.activeTexture(gl.TEXTURE0);
+        gl.bindTexture(gl.TEXTURE_2D, bgTexture);
+        gl.uniform1i(uBgTexture, 0);
+
+        gl.activeTexture(gl.TEXTURE1);
+        gl.bindTexture(gl.TEXTURE_2D, domTexture);
+        gl.uniform1i(uDomTexture, 1);
+
+        gl.uniform2f(uResolution, canvas.width, canvas.height);
+        gl.uniform2f(uMouse, mouseUV.x, mouseUV.y);
+        gl.uniform1f(uTime, now);
+        gl.uniform1f(uHoverIntensity, currentHoverIntensity);
+        gl.uniform4fv(uTitleBounds, titleBoundsUV);
+        gl.uniform4fv(uBtnBounds, btnBoundsUV);
+        gl.uniform1f(uBtnHover, currentBtnHover);
+
+        for (let i = 0; i < MAX_RIPPLES; i++) {
+          const r = ripples[i];
+          gl.uniform4f(uRipples[i], r.x, r.y, r.startTime, r.amplitude);
+        }
+
+        gl.drawArrays(gl.TRIANGLES, 0, 6);
+        requestAnimationFrame(render);
+      }
+
+      requestAnimationFrame(render);
+    })();
+  </script>
 </body>

 </html>

