+      rgba_buf[i * 4 + 1] = (uint8_t)toInt(pixel_c.y);
+      rgba_buf[i * 4 + 2] = (uint8_t)toInt(pixel_c.z);
+      rgba_buf[i * 4 + 3] = 255;
+    }
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* render_scene(int w, int h, int samps, int seed) {
+  init_render(w, h);
+  render_rows(w, h, 0, h, samps, seed);
+  return rgba_buf;
