+    (function () {
+      const themeSelect = document.getElementById('theme-select');
+      const metaColorScheme = document.querySelector('meta[name="color-scheme"]');
+      const root = document.documentElement;
+
+      function applyTheme(value) {
+        if (value === 'light' || value === 'dark') {
+          metaColorScheme.content = value;
+          root.style.colorScheme = value;
+          root.setAttribute('data-theme', value);
+        } else {
+          metaColorScheme.content = 'light dark';
+          root.style.colorScheme = 'light dark';
+          root.removeAttribute('data-theme');
+        }
+      }
+
+      // Initialize select dropdown from stored preference if present
+      try {
+        const stored = localStorage.getItem('color-scheme');
+        if (stored === 'light' || stored === 'dark') {
+          themeSelect.value = stored;
+          applyTheme(stored);
+        } else {
+          themeSelect.value = 'system';
+          applyTheme('system');
+        }
+      } catch (e) {
+        themeSelect.value = 'system';
+      }
+
+      themeSelect.addEventListener('change', (e) => {
+        const choice = e.target.value;
+        applyTheme(choice);
+        try {
+          if (choice === 'light' || choice === 'dark') {
+            localStorage.setItem('color-scheme', choice);
+          } else {
+            localStorage.removeItem('color-scheme');
+          }
+        } catch (err) {}
+      });
+
+      window.addEventListener('storage', (e) => {
+        if (e.key === 'color-scheme') {
+          const newValue = e.newValue === 'light' || e.newValue === 'dark' ? e.newValue : 'system';
+          themeSelect.value = newValue;
+          applyTheme(newValue);
+        }
+      });
+
