+  <script>
+    const viewport = document.getElementById('seasonal-viewport');
+    const cards = Array.from(viewport.querySelectorAll('.card'));
+    const prevBtn = document.getElementById('prev-btn');
+    const nextBtn = document.getElementById('next-btn');
+    const statusEl = document.getElementById('carousel-status');
+    let currentIndex = 0;
+
+    /**
+     * Navigates to a new view with a directional transition.
+     * @param {Function} updateDOM - Callback to update the DOM state.
+     * @param {string} direction - Either 'forward' or 'backward'.
+     */
+    function navigate(updateDOM, direction) {
+      if (!document.startViewTransition) {
+        updateDOM();
+        return;
+      }
+
+      const transition = document.startViewTransition({
+        update: updateDOM,
+        types: [direction]
+      });
+
+      transition.ready?.catch(() => {});
+    }
+
+    function showSlide(nextIndex, direction) {
+      navigate(() => {
+        cards[currentIndex].hidden = true;
+        currentIndex = nextIndex;
+        cards[currentIndex].hidden = false;
+        statusEl.textContent = `${currentIndex + 1} / ${cards.length}`;
+      }, direction);
+    }
+
+    nextBtn.addEventListener('click', () => {
+      const nextIndex = (currentIndex + 1) % cards.length;
+      showSlide(nextIndex, 'forward');
+    });
+
+    prevBtn.addEventListener('click', () => {
+      const prevIndex = (currentIndex - 1 + cards.length) % cards.length;
