+        if (event.key === "ArrowDown" || (isSubmenu(menu) && event.key === "ArrowRight")) {
+          event.preventDefault();
+          event.stopPropagation();
+          if (isOpen(menu)) {
+            focusElement(itemsOf(menu)[0]);
+          } else {
+            enterOnOpen.add(menu);
+            trigger.click();
+          }
+        } else if (event.key === "ArrowUp" || event.key === "End") {
+          if (!isSubmenu(menu)) {
+            event.preventDefault();
+            event.stopPropagation();
+            if (isOpen(menu)) {
+              focusElement(itemsOf(menu).at(-1));
+            } else {
+              enterLastOnOpen.add(menu);
+              trigger.click();
+            }
+          }
+        } else if (event.key === "Home" && isOpen(menu)) {
+          event.preventDefault();
+          event.stopPropagation();
+          focusElement(itemsOf(menu)[0]);
+        } else if (event.key === "Escape" && isOpen(menu)) {
+          event.preventDefault();
+          event.stopPropagation();
+          closeAndRestore(menu);
+        }
+      });
