+    document.querySelectorAll('[focusgroup~="menu"]').forEach(group => {
+      const menu = group.closest("[popover]");
+      if (!menu) return;
+
+      // Pointer move over an item focuses it without a ring and closes sibling submenus
+      group.addEventListener("pointermove", event => {
+        const item = event.target.closest("button, a");
+        if (!item || item.closest("[focusgroup]") !== group) return;
+        if (document.activeElement !== item) {
+          focusElement(item, { focusVisible: false });
+        }
+        // Close any open sibling submenu when hovering a non-trigger sibling
+        group.querySelectorAll(":scope > [popover]").forEach(sub => {
+          const subTrigger = triggerFor(sub);
+          if (subTrigger !== item && isOpen(sub) && !sub.hasAttribute("data-bridge")) {
+            sub.hidePopover();
+          }
+        });
+      });
+
+      // Keyboard navigation inside the menu (Escape, ArrowLeft in submenu, Home/End, Space on checkboxes)
+      group.addEventListener("keydown", event => {
+        if (event.target.closest("[focusgroup]") !== group) return;
+
+        if (event.key === "Escape") {
+          event.preventDefault();
+          event.stopPropagation();
+          closeAndRestore(menu);
+          return;
+        }
+
+        if (event.key === "ArrowLeft" && isSubmenu(menu)) {
+          event.preventDefault();
+          event.stopPropagation();
+          closeAndRestore(menu);
+          return;
+        }
+
+        if (event.key === "Tab") {
+          const root = rootMenuOf(menu);
+          if (root && isOpen(root)) {
+            root.hidePopover();
+          }
+          return;
+        }
