+              if (indicator) indicator.textContent = nextState ? '✓' : '';
+
+              if (customGroup) {
+                syncCardSummary(card);
+                updateStatus(
+                  `${nextState ? 'Added' : 'Removed'} <em>${customValue}</em> on <strong>${drinkName}</strong>.`,
+                  `${drinkName}: ${customValue}`
+                );
+              } else if (cardAction === 'toggle-favorite') {
+                updateStatus(
+                  `${nextState ? 'Saved' : 'Removed'} <strong>${drinkName}</strong> ${nextState ? 'to' : 'from'} your favorites.`,
+                  nextState ? `★ Saved ${drinkName}` : 'All Seasonal Favorites'
+                );
+              }
+              return;
+            }
+
+            // Action items (Add to Order, Reset, View Details)
+            if (cardAction === 'add-to-order') {
+              e.preventDefault();
+              cartItemCount += 1;
+              if (navCartCountEl) {
+                navCartCountEl.textContent = `${cartItemCount} ${cartItemCount === 1 ? 'item' : 'items'}`;
+              }
+              const priceText = card.querySelector('[data-price-display]')?.textContent || '';
+              updateStatus(
+                `Added customized <strong>${drinkName}</strong> (${priceText}) to your order!`,
+                `In Cart: ${drinkName}`
+              );
+              closeAllMenus();
+            } else if (cardAction === 'reset-custom') {
+              e.preventDefault();
+              const defaults = cardInitialStates.get(card) || [];
+              const allCheckables = card.querySelectorAll('[role="menuitemradio"], [role="menuitemcheckbox"]');
+              defaults.forEach(({ idx, checked }) => {
+                const el = allCheckables[idx];
+                if (!el) return;
+                el.setAttribute('aria-checked', String(checked));
+                const ind = el.querySelector('.menu-check-indicator');
+                if (ind) {
+                  ind.textContent = checked
+                    ? el.getAttribute('role') === 'menuitemradio'
+                      ? '●'
+                      : '✓'
+                    : '';
+                }
+              });
+              syncCardSummary(card);
+              updateStatus(
+                `Reset <strong>${drinkName}</strong> to its original seasonal recipe.`,
+                `${drinkName} (Default)`
+              );
+              closeAllMenus();
+            } else if (cardAction === 'view-details') {
+              e.preventDefault();
+              updateStatus(
+                `Viewing nutrition &amp; sourcing details for <strong>${drinkName}</strong>.`,
+                `${drinkName} Details`
+              );
+              closeAllMenus();
+            }
+          });
+        });
+
+        // Quick Add to Order primary button on each card
+        const quickOrderBtn = card.querySelector('[data-quick-order-btn]');
+        if (quickOrderBtn) {
+          quickOrderBtn.addEventListener('click', (e) => {
+            e.preventDefault();
+            cartItemCount += 1;
+            if (navCartCountEl) {
+              navCartCountEl.textContent = `${cartItemCount} ${cartItemCount === 1 ? 'item' : 'items'}`;
+            }
+            const priceText = card.querySelector('[data-price-display]')?.textContent || '';
+            updateStatus(
+              `Added <strong>${drinkName}</strong> (${priceText}) to your order!`,
+              `In Cart: ${drinkName}`
+            );
+          });
+        }
+      });
+
+      if (resetStatusBtn) {
+        resetStatusBtn.addEventListener('click', () => {
+          updateStatus(
+            'Pickup at <strong>Downtown Roastery</strong> • Customize any seasonal drink below using the interactive options menu.',
+            'All Seasonal Favorites'
+          );
+        });
+      }
+
+      // Close menus when clicking outside
+      document.addEventListener('click', (e) => {
+        if (!e.target.closest('.menu-container')) {
+          closeAllMenus();
+        }
+      });
+    })();
+  </script>
 </body>

