+++ b/src/utils/passkey-store.ts
@@ -0,0 +1,241 @@
+import crypto from 'node:crypto';
+import type { PasskeyCredentialInfo, UserProfile } from './passkeys';
+
+export interface StoredCredential extends PasskeyCredentialInfo {
+  userId: string;
+  username: string;
+  publicKey?: string | null;
+  algorithm?: number;
+  signCount: number;
+}
+
+export interface StoredUser {
+  id: string;
+  username: string;
+  displayName: string;
+  email: string;
+  passwordHash?: string;
+  createdAt: string;
+  lastReauthAt?: string | null;
+}
+
+export interface PendingChallenge {
+  challenge: string;
+  type: 'registration' | 'authentication' | 'reauthentication';
+  username?: string;
+  userId?: string;
+  createdAt: number;
+}
+
+interface PasskeyStoreState {
+  users: Map<string, StoredUser>; // keyed by lowercase username
+  usersById: Map<string, StoredUser>; // keyed by userId
+  credentials: Map<string, StoredCredential>; // keyed by credentialId (base64url)
+  challenges: Map<string, PendingChallenge>; // keyed by challenge string
+}
+
+const globalStoreKey = '__DEVTOOLS_TIMES_PASSKEY_STORE__';
+
+function getStore(): PasskeyStoreState {
+  const g = globalThis as unknown as Record<string, PasskeyStoreState>;
+  if (!g[globalStoreKey]) {
+    const store: PasskeyStoreState = {
+      users: new Map(),
+      usersById: new Map(),
+      credentials: new Map(),
+      challenges: new Map(),
+    };
+    // Seed a default demo user so Account Settings / Sign-In work out of the box if needed
+    const demoUser: StoredUser = {
+      id: 'user-devtools-editor',
+      username: 'editor',
+      displayName: 'DevTools Editor',
+      email: 'editor@devtoolstimes.dev',
+      createdAt: new Date(Date.now() - 86400000 * 14).toISOString(),
+      lastReauthAt: null,
+    };
+    store.users.set(demoUser.username.toLowerCase(), demoUser);
+    store.usersById.set(demoUser.id, demoUser);
+    g[globalStoreKey] = store;
+  }
+  return g[globalStoreKey];
+}
+
+export function generateChallengeBytes(): string {
+  return crypto.randomBytes(32).toString('base64url');
+}
+
+export function createChallenge(
+  type: PendingChallenge['type'],
+  username?: string,
+  userId?: string
+): PendingChallenge {
+  const store = getStore();
+  // Clean up expired challenges (> 10 minutes)
+  const now = Date.now();
+  for (const [key, value] of store.challenges.entries()) {
+    if (now - value.createdAt > 10 * 60 * 1000) {
+      store.challenges.delete(key);
+    }
+  }
+
+  const challenge = generateChallengeBytes();
+  const entry: PendingChallenge = {
+    challenge,
+    type,
+    username,
+    userId,
+    createdAt: now,
+  };
+  store.challenges.set(challenge, entry);
+  return entry;
+}
+
+export function consumeChallenge(challenge?: string): PendingChallenge | null {
+  if (!challenge) return null;
+  const store = getStore();
+  const entry = store.challenges.get(challenge);
+  if (entry) {
+    store.challenges.delete(challenge);
+    return entry;
+  }
+  return null;
+}
+
+export function getOrCreateUser(username: string, displayName?: string): StoredUser {
+  const store = getStore();
+  const normalized = username.trim().toLowerCase();
+  const existing = store.users.get(normalized);
+  if (existing) {
+    if (displayName && displayName.trim()) {
+      existing.displayName = displayName.trim();
+    }
+    return existing;
+  }
+
+  const userId = `user-${crypto.randomBytes(8).toString('hex')}`;
+  const cleanUsername = username.trim();
+  const newUser: StoredUser = {
+    id: userId,
+    username: cleanUsername,
+    displayName: displayName?.trim() || cleanUsername,
+    email: cleanUsername.includes('@') ? cleanUsername : `${cleanUsername}@devtoolstimes.dev`,
+    createdAt: new Date().toISOString(),
+    lastReauthAt: new Date().toISOString(),
+  };
+
+  store.users.set(normalized, newUser);
+  store.usersById.set(userId, newUser);
+  return newUser;
+}
+
+export function getUserByUsername(username: string): StoredUser | null {
+  const store = getStore();
+  return store.users.get(username.trim().toLowerCase()) || null;
+}
+
+export function getUserById(userId: string): StoredUser | null {
+  const store = getStore();
+  return store.usersById.get(userId) || null;
+}
+
+export function getCredentialsForUser(usernameOrId: string): StoredCredential[] {
+  const store = getStore();
+  const normalized = usernameOrId.trim().toLowerCase();
+  const results: StoredCredential[] = [];
+  for (const cred of store.credentials.values()) {
+    if (cred.username.toLowerCase() === normalized || cred.userId === usernameOrId) {
+      results.push(cred);
+    }
+  }
+  return results;
+}
+
+export function getCredentialById(credentialId: string): StoredCredential | null {
+  const store = getStore();
+  return store.credentials.get(credentialId) || null;
+}
+
+export function saveCredential(credential: StoredCredential): StoredCredential {
+  const store = getStore();
+  store.credentials.set(credential.id, credential);
+  return credential;
+}
+
+export function renameCredential(
+  username: string,
+  credentialId: string,
+  newName: string
+): StoredCredential | null {
+  const store = getStore();
+  const cred = store.credentials.get(credentialId);
+  if (!cred || cred.username.toLowerCase() !== username.toLowerCase()) {
+    return null;
+  }
+  cred.name = newName.trim() || cred.name;
+  store.credentials.set(credentialId, cred);
+  return cred;
+}
+
+export function deleteCredential(username: string, credentialId: string): boolean {
+  const store = getStore();
+  const cred = store.credentials.get(credentialId);
+  if (!cred || cred.username.toLowerCase() !== username.toLowerCase()) {
+    return false;
+  }
+  return store.credentials.delete(credentialId);
+}
+
+export function touchCredentialUsage(credentialId: string): StoredCredential | null {
+  const store = getStore();
+  const cred = store.credentials.get(credentialId);
+  if (!cred) return null;
+  cred.lastUsedAt = new Date().toISOString();
+  cred.signCount = (cred.signCount || 0) + 1;
+  store.credentials.set(credentialId, cred);
+  return cred;
+}
+
+export function markUserReauthenticated(username: string): StoredUser | null {
+  const user = getUserByUsername(username);
+  if (!user) return null;
+  user.lastReauthAt = new Date().toISOString();
+  return user;
+}
+
+export function buildUserProfile(user: StoredUser): UserProfile {
+  const passkeys = getCredentialsForUser(user.username).map((c) => ({
+    id: c.id,
+    name: c.name,
+    createdAt: c.createdAt,
+    lastUsedAt: c.lastUsedAt,
+    transports: c.transports,
+    deviceType: c.deviceType,
+    backedUp: c.backedUp,
+    aaguid: c.aaguid,
+  }));
+
+  return {
+    id: user.id,
+    username: user.username,
+    displayName: user.displayName,
+    email: user.email,
+    createdAt: user.createdAt,
+    lastReauthAt: user.lastReauthAt,
+    passkeys,
+  };
+}
+
+export function decodeClientDataJSON(base64Url?: string): {
+  type?: string;
+  challenge?: string;
+  origin?: string;
+} | null {
+  if (!base64Url) return null;
+  try {
+    const json = Buffer.from(base64Url, 'base64url').toString('utf-8');
+    return JSON.parse(json);
+  } catch {
+    return null;
+  }
+}
diff --git a/src/utils/passkeys.ts b/src/utils/passkeys.ts
new file mode 100644
index 0000000..4f0f98f
--- /dev/null
+++ b/src/utils/passkeys.ts
@@ -0,0 +1,217 @@
+/**
+ * WebAuthn / Passkey utility helpers and client/server shared types
+ */
+
+export interface PasskeyCredentialInfo {
+  id: string; // Base64URL encoded credential ID
+  name: string;
+  createdAt: string;
+  lastUsedAt?: string | null;
+  transports?: AuthenticatorTransport[];
+  deviceType?: 'singleDevice' | 'multiDevice';
+  backedUp?: boolean;
+  aaguid?: string;
+}
+
+export interface UserProfile {
+  id: string;
+  username: string;
+  displayName: string;
+  email?: string;
+  createdAt: string;
+  lastReauthAt?: string | null;
+  passkeys: PasskeyCredentialInfo[];
+}
+
+export function bufferToBase64Url(buffer: ArrayBuffer | Uint8Array): string {
+  const bytes = buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer);
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return btoa(binary)
+    .replace(/\+/g, '-')
+    .replace(/\//g, '_')
+    .replace(/=+$/g, '');
+}
+
+export function base64UrlToBuffer(base64Url: string): ArrayBuffer {
+  const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
+  const padLen = (4 - (base64.length % 4)) % 4;
+  const padded = base64 + '='.repeat(padLen);
+  const binary = atob(padded);
+  const bytes = new Uint8Array(binary.length);
+  for (let i = 0; i < binary.length; i++) {
+    bytes[i] = binary.charCodeAt(i);
+  }
+  return bytes.buffer;
+}
+
+export function isWebAuthnSupported(): boolean {
+  return (
+    typeof window !== 'undefined' &&
+    typeof window.PublicKeyCredential !== 'undefined' &&
+    typeof navigator.credentials !== 'undefined'
+  );
+}
+
+export async function isConditionalMediationAvailable(): Promise<boolean> {
+  if (!isWebAuthnSupported()) return false;
+  if (typeof PublicKeyCredential.isConditionalMediationAvailable === 'function') {
+    try {
+      return await PublicKeyCredential.isConditionalMediationAvailable();
+    } catch {
+      return false;
+    }
+  }
+  return false;
+}
+
+export async function isPlatformAuthenticatorAvailable(): Promise<boolean> {
+  if (!isWebAuthnSupported()) return false;
+  if (typeof PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable === 'function') {
+    try {
+      return await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
+    } catch {
+      return false;
+    }
+  }
+  return false;
+}
+
+export function detectDefaultPasskeyName(): string {
+  if (typeof navigator === 'undefined') return 'Passkey';
+  const ua = navigator.userAgent || '';
+  if (/Macintosh|Mac OS X/i.test(ua)) return 'iCloud Keychain / Mac Passkey';
+  if (/iPhone|iPad|iPod/i.test(ua)) return 'iCloud Keychain';
+  if (/Android/i.test(ua)) return 'Google Password Manager';
+  if (/Windows/i.test(ua)) return 'Windows Hello';
+  if (/Linux/i.test(ua)) return 'Chrome Profile Passkey';
+  return 'Passkey on this device';
+}
+
+export function serializeRegistrationCredential(credential: PublicKeyCredential) {
+  const response = credential.response as AuthenticatorAttestationResponse;
+  const transports =
+    typeof response.getTransports === 'function'
+      ? (response.getTransports() as AuthenticatorTransport[])
+      : (['internal', 'hybrid'] as AuthenticatorTransport[]);
+
+  const publicKeyBuffer =
+    typeof response.getPublicKey === 'function' ? response.getPublicKey() : null;
+  const publicKeyAlgorithm =
+    typeof response.getPublicKeyAlgorithm === 'function'
+      ? response.getPublicKeyAlgorithm()
+      : -7;
+
+  return {
+    id: credential.id,
+    rawId: bufferToBase64Url(credential.rawId),
+    type: credential.type,
+    authenticatorAttachment: (credential as any).authenticatorAttachment || 'platform',
+    response: {
+      clientDataJSON: bufferToBase64Url(response.clientDataJSON),
+      attestationObject: bufferToBase64Url(response.attestationObject),
+      transports,
+      publicKey: publicKeyBuffer ? bufferToBase64Url(publicKeyBuffer) : null,
+      publicKeyAlgorithm,
+    },
+    clientExtensionResults: credential.getClientExtensionResults?.() || {},
+  };
+}
+
+export function serializeAuthenticationCredential(credential: PublicKeyCredential) {
+  const response = credential.response as AuthenticatorAssertionResponse;
+  return {
+    id: credential.id,
+    rawId: bufferToBase64Url(credential.rawId),
+    type: credential.type,
+    authenticatorAttachment: (credential as any).authenticatorAttachment || 'platform',
+    response: {
+      clientDataJSON: bufferToBase64Url(response.clientDataJSON),
+      authenticatorData: bufferToBase64Url(response.authenticatorData),
+      signature: bufferToBase64Url(response.signature),
+      userHandle: response.userHandle ? bufferToBase64Url(response.userHandle) : null,
+    },
+    clientExtensionResults: credential.getClientExtensionResults?.() || {},
+  };
+}
+
+export function formatPasskeyError(err: unknown, fallback = 'Passkey operation failed.'): string {
+  if (!err) return fallback;
+  if (err instanceof DOMException || (typeof err === 'object' && err !== null && 'name' in err)) {
+    const name = (err as { name: string; message?: string }).name;
+    const message = (err as { name: string; message?: string }).message;
+    switch (name) {
+      case 'NotAllowedError':
+        return 'The passkey request was cancelled or timed out.';
+      case 'InvalidStateError':
+        return 'A passkey for this authenticator is already registered for this account.';
+      case 'NotSupportedError':
+        return 'Passkeys (WebAuthn) are not supported by this browser or authenticator.';
+      case 'SecurityError':
+        return 'Security error: The relying party ID is invalid for this domain.';
+      case 'AbortError':
+        return 'The passkey operation was aborted.';
+      default:
+        return message || fallback;
+    }
+  }
+  if (err instanceof Error) return err.message;
+  return String(err);
+}
+
+const LOCAL_STORAGE_USER_KEY = 'devtools_times_user';
+const LOCAL_STORAGE_PASSKEYS_KEY = 'devtools_times_passkeys';
+
+export function getLocalPasskeys(username?: string): PasskeyCredentialInfo[] {
+  if (typeof window === 'undefined') return [];
+  try {
+    const raw = localStorage.getItem(LOCAL_STORAGE_PASSKEYS_KEY);
+    if (!raw) return [];
+    const map = JSON.parse(raw) as Record<string, PasskeyCredentialInfo[]>;
+    if (username) {
+      return map[username.toLowerCase()] || [];
+    }
+    return Object.values(map).flat();
+  } catch {
+    return [];
+  }
+}
+
+export function saveLocalPasskeys(username: string, passkeys: PasskeyCredentialInfo[]) {
+  if (typeof window === 'undefined' || !username) return;
+  try {
+    const raw = localStorage.getItem(LOCAL_STORAGE_PASSKEYS_KEY);
+    const map = raw ? (JSON.parse(raw) as Record<string, PasskeyCredentialInfo[]>) : {};
+    map[username.toLowerCase()] = passkeys;
+    localStorage.setItem(LOCAL_STORAGE_PASSKEYS_KEY, JSON.stringify(map));
+  } catch {
+    // ignore storage errors
+  }
+}
+
+export function saveLocalUserSession(user: UserProfile | null) {
+  if (typeof window === 'undefined') return;
+  try {
+    if (user) {
+      localStorage.setItem(LOCAL_STORAGE_USER_KEY, JSON.stringify(user));
+      saveLocalPasskeys(user.username, user.passkeys || []);
+    } else {
+      localStorage.removeItem(LOCAL_STORAGE_USER_KEY);
+    }
+    window.dispatchEvent(new CustomEvent('devtools-auth-changed', { detail: { user } }));
+  } catch {
+    // ignore storage errors
+  }
+}
+
+export function getLocalUserSession(): UserProfile | null {
+  if (typeof window === 'undefined') return null;
+  try {
+    const raw = localStorage.getItem(LOCAL_STORAGE_USER_KEY);
+    return raw ? (JSON.parse(raw) as UserProfile) : null;
+  } catch {
+    return null;
+  }
+}

