@@ -0,0 +1,72 @@
+import type { APIRoute } from 'astro';
+import { randomInt } from 'node:crypto';
+import { formatOriginBoundSms } from '../../utils/sms-otp';
+
+export const POST: APIRoute = async ({ request, url, session }) => {
+  try {
+    let phone = '';
+    let username = '';
+
+    const contentType = request.headers.get('content-type') || '';
+    if (contentType.includes('application/json')) {
+      const body = await request.json();
+      phone = (body.phone || '').toString().trim();
+      username = (body.username || '').toString().trim();
+    } else {
+      const formData = await request.formData();
+      phone = (formData.get('phone') || '').toString().trim();
+      username = (formData.get('username') || '').toString().trim();
+    }
+
+    if (!phone || !/^\+?[0-9\s\-()]{7,20}$/.test(phone)) {
+      return new Response(
+        JSON.stringify({
+          error: 'INVALID_PHONE',
+          message: 'Please enter a valid phone number.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    // Generate a 6-digit numeric OTP string (preserving leading zeros like "012345")
+    const otpCode = randomInt(0, 1_000_000).toString().padStart(6, '0');
+    const originHeader = request.headers.get('origin') || url.origin;
+    const smsMessage = formatOriginBoundSms(originHeader, otpCode);
+
+    if (session) {
+      await session.set('pendingOtp', {
+        code: otpCode,
+        phone,
+        username,
+        expiresAt: Date.now() + 10 * 60 * 1000,
+      });
+    }
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        phone,
+        message: 'Verification code sent via SMS.',
+        smsMessage,
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({
+        error: 'SERVER_ERROR',
+        message: 'Unable to send SMS verification code. Please try again.',
+      }),
+      {
+        status: 500,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};
