-}
\ No newline at end of file
+}
+
+/* 1. Semantic Context Containers */
+.surface-lead,
+[data-surface="lead"] {
+  --surface: lead;
+}
+
+.surface-featured,
+[data-surface="featured"] {
+  --surface: featured;
+}
+
+.surface-spotlight,
+[data-surface="spotlight"] {
+  --surface: spotlight;
+}
+
+.surface-compact,
+[data-surface="compact"] {
+  --surface: compact;
+}
+
+.surface-related,
