+  --surface: related;
+}
+
+/* 2. Default Component Styles (Work everywhere) */
+.article-teaser {
+  display: flex;
+  flex-direction: column;
+  height: 100%;
+  background: var(--surface-bg);
+}
+
+.article-teaser__layout {
+  display: flex;
+  flex-direction: column;
+  height: 100%;
+  gap: 0.75rem;
+}
+
+.article-teaser__media {
+  display: block;
+  overflow: clip;
+  border-radius: 0.375rem;
+  flex-shrink: 0;
+}
+
+.article-teaser__image {
+  width: 100%;
+  height: auto;
+  object-fit: cover;
+  aspect-ratio: 16 / 9;
+}
+
+.article-teaser__body {
+  display: flex;
+  flex-direction: column;
+  flex-grow: 1;
+}
+
+.article-teaser__badge {
+  display: none;
+  align-self: flex-start;
+  font-size: 0.75rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: 0.05em;
+  padding: 0.125rem 0.5rem;
+  border-radius: 9999px;
+  background: var(--brand-accent);
+  color: #111827;
+  margin-block-end: 0.5rem;
+}
+
+.article-teaser__category {
+  color: var(--brand-accent-dark);
+  font-size: 0.875rem;
+  letter-spacing: 0.1em;
+}
+
+.article-teaser__title {
+  font-size: 1.25rem;
+  line-height: 1.35;
+  color: #1f2937;
+  margin-block-start: 0.25rem;
+}
+
+.article-teaser__summary {
+  color: #4b5563;
+  margin-block-start: 0.25rem;
+  flex-grow: 1;
+}
+
+.article-teaser__footer {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  color: #6b7280;
+  margin-block-start: 0.75rem;
+  padding-block-start: 0.5rem;
+  border-block-start: 1px solid var(--border-subtle);
+}
+
+.article-teaser__cta {
+  /* Default: Outlined informational style */
+  display: inline-flex;
+  align-items: center;
+  gap: 0.25rem;
