+}
+
+.article-teaser__cta:hover {
+  color: #111827;
+}
+
+.bookmark-button {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.25rem;
+  padding: 0.25rem;
+  border-radius: 0.25rem;
