+          orderIdText.textContent = String(data.orderId);
+        }
+        if (itemText && data.item) {
+          itemText.textContent = String(data.item);
+        }
+        if (verifiedOriginText) {
+          verifiedOriginText.textContent = event.origin;
+        }
