+import { createServer } from 'node:http';
+import { createHash, randomBytes } from 'node:crypto';
+import dns from 'node:dns/promises';
+import { readFile } from 'node:fs/promises';
+import { extname, join, normalize } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { decodeSdJwtSync, SDJwtInstance } from '@sd-jwt/core';
+import { createRemoteJWKSet, importJWK, jwtVerify } from 'jose';
+
+const __dirname = fileURLToPath(new URL('.', import.meta.url));
+const PORT = Number(process.env.PORT || 11222);
+const RP_ORIGIN = process.env.RP_ORIGIN || `http://localhost:${PORT}`;
+const ORIGIN_TRIAL_TOKEN = process.env.ORIGIN_TRIAL_TOKEN || 'ORIGIN_TRIAL_TOKEN_PLACEHOLDER';
+
+// Server-side session store mapping session ID -> expected single-use nonce
+const sessionNonceStore = new Map();
+// Registered rewards accounts store
+const rewardsAccounts = new Map();
+
+// IETF draft-hardt-email-verification-02 (§3.3, §5.1.1) specifies RFC 9864 'Ed25519' and 'ES256'.
+// TODO: Remove 'EdDSA' once live issuers (e.g. Gmail) and Chrome Origin Trial builds finish
+// transitioning from 'EdDSA' (with crv: 'Ed25519') to 'Ed25519'.
+const ALLOWED_ALGS = ['Ed25519', 'EdDSA', 'ES256'];
+const normalizeAlg = (alg) => (alg === 'Ed25519' ? 'EdDSA' : alg);
+
+const hasher = (data, alg) =>
+  createHash(alg === 'sha-256' ? 'sha256' : alg).update(data).digest();
+
+export function generateSessionNonce() {
+  return randomBytes(32).toString('base64url');
+}
+
+export function parseCookies(cookieHeader = '') {
+  const cookies = {};
+  for (const part of cookieHeader.split(';')) {
+    const [rawKey, ...rest] = part.trim().split('=');
+    if (rawKey) {
+      cookies[rawKey] = decodeURIComponent(rest.join('='));
+    }
+  }
+  return cookies;
+}
+
+export function createSessionWithNonce(existingSessionId) {
+  const sessionId = existingSessionId || randomBytes(24).toString('base64url');
+  const nonce = generateSessionNonce();
+  sessionNonceStore.set(sessionId, nonce);
+  return { sessionId, nonce };
+}
+
+export function consumeSessionNonce(sessionId) {
+  if (!sessionId || !sessionNonceStore.has(sessionId)) {
+    return null;
+  }
+  // Atomically read and delete the single-use nonce from server-side session state
+  const expectedNonce = sessionNonceStore.get(sessionId);
+  sessionNonceStore.delete(sessionId);
+  return expectedNonce;
+}
+
+export async function verifyEmailVerificationToken({
+  rawToken,
+  submittedEmail,
+  expectedNonce,
+  expectedAudience = RP_ORIGIN,
+}) {
+  // Step 1: Parse the SD-JWT claims and validate the email address
+  const decoded = decodeSdJwtSync(rawToken, hasher);
+  const evtPayload = decoded.jwt?.payload;
+  const iss = evtPayload?.iss;
