+}
+
+function completeAccountCreation(submittedEmail, submittedName, nextNonce) {
+  rewardsAccounts.set(submittedEmail.toLowerCase(), {
+    email: submittedEmail,
+    name: submittedName,
+    emailVerified: true,
+    verifiedVia: 'EVP',
+    createdAt: new Date().toISOString(),
+  });
+  return {
+    status: 'verified',
+    verified: true,
+    email: submittedEmail,
+    nextNonce,
+    message: `Welcome to Daily Grind Rewards, ${submittedName || submittedEmail}! Your email ownership was verified automatically.`,
+  };
+}
+
+function sendTraditionalVerificationEmail(submittedEmail, submittedName, nextNonce) {
+  rewardsAccounts.set(submittedEmail.toLowerCase(), {
+    email: submittedEmail,
+    name: submittedName,
+    emailVerified: false,
+    verifiedVia: 'pending-email-fallback',
+    createdAt: new Date().toISOString(),
+  });
