+    status: 'fallback_verification_sent',
+    verified: false,
+    email: submittedEmail,
+    nextNonce,
+    message: `We sent a verification link to ${submittedEmail} to complete your Daily Grind Rewards registration.`,
+  };
+}
+
+async function readRequestBody(req) {
+  const chunks = [];
+  for await (const chunk of req) {
+    chunks.push(chunk);
+  }
+  return Buffer.concat(chunks).toString('utf8');
+}
+
+function parseSubmittedFields(rawBody, contentType = '') {
+  if (contentType.includes('application/json')) {
+    try {
+      return JSON.parse(rawBody);
+    } catch {
+      return {};
+    }
+  }
+  const params = new URLSearchParams(rawBody);
+  return Object.fromEntries(params.entries());
+}
+
+export async function handleSignupSubmission(req, res) {
+  const cookies = parseCookies(req.headers.cookie);
+  const sessionId = cookies.dg_sid;
+  // Atomically read and delete the single-use nonce from server-side session state
+  const expectedNonce = consumeSessionNonce(sessionId);
+
+  const rawBody = await readRequestBody(req);
+  const fields = parseSubmittedFields(rawBody, req.headers['content-type'] || '');
+  const submittedEmail = String(fields.email || '').trim();
+  const submittedName = String(fields.name || '').trim();
+  const rawToken = String(fields.token || '').trim();
+
+  // Issue a fresh nonce in session state for any subsequent form submission
+  const { sessionId: activeSessionId, nonce: nextNonce } = createSessionWithNonce(sessionId);
+  const hostHeader = req.headers.host;
+  const proto = req.headers['x-forwarded-proto'] || 'http';
+  const expectedAudience = process.env.RP_ORIGIN || (hostHeader ? `${proto}://${hostHeader}` : RP_ORIGIN);
+
+  let result;
+  if (rawToken && expectedNonce) {
+    try {
+      await verifyEmailVerificationToken({
+        rawToken,
+        submittedEmail,
+        expectedNonce,
+        expectedAudience,
+      });
+      // Fast path: email ownership is cryptographically verified; skip OTP email.
+      result = completeAccountCreation(submittedEmail, submittedName, nextNonce);
+    } catch (err) {
+      // Log token verification failures before falling back to standard email verification.
+      console.error('Email verification token check failed:', err);
+      result = sendTraditionalVerificationEmail(submittedEmail, submittedName, nextNonce);
+    }
+  } else {
+    // Fallback path: send standard OTP code or magic link email to submittedEmail.
+    result = sendTraditionalVerificationEmail(submittedEmail, submittedName, nextNonce);
+  }
+
+  const setCookieHeader = `dg_sid=${encodeURIComponent(activeSessionId)}; Path=/; HttpOnly; Secure; SameSite=Lax`;
+  const accept = req.headers.accept || '';
+
+  if (accept.includes('application/json') || (req.headers['content-type'] || '').includes('application/json')) {
+    res.writeHead(200, {
+      'Content-Type': 'application/json; charset=utf-8',
+      'Cache-Control': 'no-store',
+      'Set-Cookie': setCookieHeader,
+    });
+    res.end(JSON.stringify(result));
+    return;
+  }
+
+  res.writeHead(200, {
+    'Content-Type': 'text/html; charset=utf-8',
+    'Cache-Control': 'no-store',
+    'Set-Cookie': setCookieHeader,
+  });
+  res.end(`<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <title>Daily Grind Rewards</title>
+</head>
+<body>
+  <main>
+    <h1>${result.verified ? 'Rewards Account Created' : 'Verify Your Email'}</h1>
+    <p>${result.message}</p>
+    <a href="/">Return to The Daily Grind</a>
+  </main>
+</body>
+</html>`);
+}
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+};
+
+export const server = createServer(async (req, res) => {
+  try {
+    const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+
+    if (req.method === 'POST' && (url.pathname === '/api/verify-email' || url.pathname === '/rewards/signup')) {
+      await handleSignupSubmission(req, res);
+      return;
+    }
+
+    if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
+      const cookies = parseCookies(req.headers.cookie);
+      const { sessionId, nonce } = createSessionWithNonce(cookies.dg_sid);
+      const rawHtml = await readFile(join(__dirname, 'index.html'), 'utf8');
+      const renderedHtml = rawHtml
+        .replaceAll('SERVER_GENERATED_PER_FORM_NONCE', nonce)
+        .replaceAll('ORIGIN_TRIAL_TOKEN_PLACEHOLDER', ORIGIN_TRIAL_TOKEN);
+
+      res.writeHead(200, {
+        'Content-Type': 'text/html; charset=utf-8',
+        'Cache-Control': 'no-store',
+        'Origin-Trial': ORIGIN_TRIAL_TOKEN,
+        'Set-Cookie': `dg_sid=${encodeURIComponent(sessionId)}; Path=/; HttpOnly; Secure; SameSite=Lax`,
+      });
+      res.end(renderedHtml);
+      return;
+    }
+
+    if (req.method === 'GET') {
+      const safePath = normalize(url.pathname).replace(/^(\.\.(\/|\\|$))+/, '');
+      const filePath = join(__dirname, safePath);
+      const content = await readFile(filePath);
+      const ext = extname(filePath);
+      res.writeHead(200, {
+        'Content-Type': MIME_TYPES[ext] || 'application/octet-stream',
+      });
+      res.end(content);
+      return;
+    }
+
+    res.writeHead(405, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Method Not Allowed');
+  } catch (err) {
+    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Not Found');
+  }
+});
+
+if (process.argv[1] && fileURLToPath(import.meta.url) === normalize(process.argv[1])) {
+  server.listen(PORT, () => {
+    console.log(`Daily Grind server listening on http://localhost:${PORT}`);
+  });
+}

