+            <button type="button" class="close-btn" aria-label="Close coffee bag">✕</button>
+          </div>
+
+          ${this._items.length === 0 ? `
+            <div class="empty-msg">
+              <p>Your coffee bag is empty. Add a seasonal favorite to get started!</p>
+            </div>
+          ` : `
+            <ul class="items-list">
+              ${this._items.map(item => `
+                <li class="cart-item">
+                  <div>
+                    <p class="item-title">${item.name}</p>
+                    <span class="item-meta">${item.size}${item.milk ? ` • ${item.milk}` : ''} • $${item.price.toFixed(2)} each</span>
+                  </div>
+                  <div class="qty-controls">
+                    <button type="button" class="qty-btn" data-key="${item.key}" data-delta="-1" aria-label="Decrease quantity of ${item.name}">−</button>
+                    <span aria-live="polite">${item.qty}</span>
+                    <button type="button" class="qty-btn" data-key="${item.key}" data-delta="1" aria-label="Increase quantity of ${item.name}">+</button>
+                  </div>
+                </li>
+              `).join('')}
+            </ul>
+            <div class="drawer-footer">
+              <div class="subtotal-row">
+                <span>Estimated Total</span>
+                <span>$${this.subtotal.toFixed(2)}</span>
