+}
+
+/**
+ * 8. <coffee-footer>
+ * Accessible footer Web Component with interactive newsletter signup validation and links.
+ */
+class CoffeeFooter extends HTMLElement {
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+  }
+
+  connectedCallback() {
+    this.render();
+    this._setupForm();
+  }
+
+  _setupForm() {
+    const form = this.shadowRoot.querySelector('form');
+    const feedback = this.shadowRoot.querySelector('.newsletter-feedback');
+    if (form && feedback) {
+      form.addEventListener('submit', (e) => {
+        e.preventDefault();
+        const emailInput = form.querySelector('input[type="email"]');
+        const email = emailInput ? emailInput.value.trim() : '';
+        if (!email || !email.includes('@')) {
+          feedback.textContent = 'Please enter a valid email address.';
+          feedback.className = 'newsletter-feedback error';
+          return;
+        }
+        feedback.textContent = `Thanks for joining the Roast Club! Check ${email} for 15% off your next cup.`;
+        feedback.className = 'newsletter-feedback success';
+        form.reset();
+      });
+    }
+  }
+
+  render() {
+    this.shadowRoot.innerHTML = `
+      <style>
+        ${sharedStyles}
+        :host {
+          display: block;
+          margin-top: 60px;
+        }
+
+        footer {
+          background: var(--dg-secondary);
+          color: var(--dg-text);
+          text-align: center;
+          padding: 48px 20px;
+        }
+
+        .newsletter-box {
+          max-width: 520px;
+          margin: 0 auto 32px;
+          background: rgba(255, 255, 255, 0.65);
+          padding: 22px;
+          border-radius: var(--dg-radius);
+        }
+
+        .newsletter-box h3 {
+          margin: 0 0 6px;
+          color: var(--dg-primary);
+        }
+
+        .newsletter-box p {
+          margin: 0 0 14px;
+          font-size: 0.9rem;
+          color: var(--dg-text-muted);
+        }
+
+        .form-row {
+          display: flex;
+          gap: 8px;
+          flex-wrap: wrap;
+        }
+
+        input[type="email"] {
+          flex: 1;
+          min-width: 200px;
+          padding: 10px 14px;
+          border: 1px solid rgba(78, 52, 46, 0.3);
+          border-radius: 6px;
+          font-size: 0.9rem;
+        }
+
+        button[type="submit"] {
+          background: var(--dg-primary);
+          color: #ffffff;
+          border: none;
+          padding: 10px 18px;
+          border-radius: 6px;
+          font-weight: 700;
+          cursor: pointer;
+          transition: background 0.2s;
+        }
+
+        button[type="submit"]:hover {
+          background: var(--dg-primary-dark);
+        }
+
+        .newsletter-feedback {
+          margin-top: 10px;
+          font-size: 0.85rem;
+          font-weight: 600;
+          min-height: 1.2em;
+        }
+
+        .newsletter-feedback.success {
+          color: #1b5e20;
+        }
+
+        .newsletter-feedback.error {
+          color: #b71c1c;
+        }
+
+        .footer-links {
+          margin-bottom: 18px;
+          display: flex;
+          justify-content: center;
+          flex-wrap: wrap;
+          gap: 16px;
+        }
+
+        .footer-links a {
+          color: var(--dg-text);
+          text-decoration: none;
+          font-size: 0.9rem;
+          font-weight: 600;
+        }
+
+        .footer-links a:hover {
+          text-decoration: underline;
+          color: var(--dg-primary);
+        }
+
+        .copyright {
+          font-size: 0.88rem;
+          color: var(--dg-text-muted);
+          margin: 0;
+        }
+      </style>
+
+      <footer part="footer" role="contentinfo">
+        <div class="newsletter-box" part="newsletter">
+          <h3>Join the Daily Grind Roast Club</h3>
+          <p>Get early access to single-origin micro-lots and seasonal tasting notes.</p>
+          <form novalidate aria-label="Newsletter subscription">
+            <div class="form-row">
+              <input
+                type="email"
+                name="email"
+                placeholder="you@example.com"
+                required
+                aria-label="Email address for Roast Club newsletter"
+              />
+              <button type="submit">Subscribe</button>
+            </div>
+            <div class="newsletter-feedback" role="status" aria-live="polite"></div>
+          </form>
+        </div>
+
+        <nav class="footer-links" aria-label="Footer Links">
+          <a href="/about">Our Story</a>
+          <a href="/careers">Join the Team</a>
+          <a href="/contact">Contact Us</a>
+          <a href="/privacy-policy">Privacy</a>
+        </nav>
+
+        <p class="copyright">&copy; 2026 The Daily Grind Coffee Co. All rights reserved.</p>
+      </footer>
+    `;
+  }
+}
+
+// Register all Custom Elements safely
+const componentRegistry = [
+  ['coffee-navbar', CoffeeNavbar],
+  ['coffee-hero', CoffeeHero],
+  ['coffee-card', CoffeeCard],
+  ['coffee-menu-section', CoffeeMenuSection],
+  ['coffee-brew-guide', CoffeeBrewGuide],
+  ['coffee-details-modal', CoffeeDetailsModal],
+  ['coffee-cart-drawer', CoffeeCartDrawer],
+  ['coffee-footer', CoffeeFooter]
+];
+
+componentRegistry.forEach(([tagName, clazz]) => {
+  if (!customElements.get(tagName)) {
+    customElements.define(tagName, clazz);
+  }
+});
+
+// Wire up page-level cross-component interactions once DOM is ready
+function initDailyGrindPage() {
+  const navbar = document.querySelector('coffee-navbar');
+  const modal = document.querySelector('coffee-details-modal');
+  const cartDrawer = document.querySelector('coffee-cart-drawer');
+  const menuSection = document.querySelector('coffee-menu-section');
+
+  document.addEventListener('coffee-view-details', (e) => {
+    if (modal && e.detail) {
+      e.preventDefault();
+      modal.open(e.detail);
+    }
+  });
+
+  document.addEventListener('coffee-add-to-cart', (e) => {
+    if (cartDrawer && e.detail) {
+      cartDrawer.addItem(e.detail);
+    }
+  });
+
+  document.addEventListener('cart-updated', (e) => {
+    if (navbar && e.detail) {
+      navbar.setAttribute('cart-count', String(e.detail.count));
+    }
+  });
+
+  document.addEventListener('cart-toggle', () => {
+    if (cartDrawer) {
+      cartDrawer.toggle();
+    }
+  });
+
+  document.addEventListener('hero-explore', () => {
+    if (menuSection) {
+      menuSection.scrollIntoView({ behavior: 'smooth' });
+    }
+  });
+}
+
+if (document.readyState === 'loading') {
+  document.addEventListener('DOMContentLoaded', initDailyGrindPage);
+} else {
+  initDailyGrindPage();
+}
